#nullable enable // autogenerated

using MVZ2.GameContent.Artifacts;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2Logic;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.zombieCow)]
    public class ZombieCow : EntityBehaviourDefinition
    {
        public ZombieCow(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            var level = entity.Level;
            var artifactID = VanillaArtifactID.cowHorn;
            if (Global.Saves.IsArtifactUnlocked(artifactID))
                return;
            if (level.HasUnlockArtifactPickup(artifactID))
                return;
            entity.Level.SpawnUnlockArtifactPickup(artifactID, entity.Position, entity);
        }
    }
}
